import { createContext, useContext, useEffect, useId, useRef, useState, useSyncExternalStore, type ReactNode } from 'react'
import { DialogQueue, confirmResult, promptResult } from './dialogQueue'
import { cx, fieldClass } from './ui'

export interface ConfirmOptions {
  title: string
  body?: ReactNode
  confirmLabel: string
  cancelLabel?: string
  tone?: 'danger' | 'default'
}

export interface PromptOptions {
  title: string
  label: string
  initial?: string
  maxLength?: number
  confirmLabel: string
  cancelLabel?: string
}

type Request = ({ kind: 'confirm' } & ConfirmOptions) | ({ kind: 'prompt' } & PromptOptions)
type Answer = boolean | string | null

const DEFAULT_CANCEL = 'Zrušiť'
const DEFAULT_MAX_LENGTH = 120

const DialogContext = createContext<DialogQueue<Request, Answer> | null>(null)

function useQueue() {
  const queue = useContext(DialogContext)
  if (!queue) throw new Error('useConfirm/usePrompt must be used inside <ConfirmProvider>')
  return queue
}

/** Asks a yes/no question in a modal dialog; resolves true only when the confirm button was used. */
export function useConfirm(): (opts: ConfirmOptions) => Promise<boolean> {
  const queue = useQueue()
  return (opts) => queue.request({ kind: 'confirm', ...opts }) as Promise<boolean>
}

/** Asks for a short text in a modal dialog; resolves the trimmed text, or null when cancelled. */
export function usePrompt(): (opts: PromptOptions) => Promise<string | null> {
  const queue = useQueue()
  return (opts) => queue.request({ kind: 'prompt', ...opts }) as Promise<string | null>
}

export function ConfirmProvider({ children }: { children: ReactNode }) {
  const [queue] = useState(() => new DialogQueue<Request, Answer>())
  const current = useSyncExternalStore(queue.subscribe, queue.current, () => null)
  return (
    <DialogContext.Provider value={queue}>
      {children}
      {current && <RequestDialog key={current.id} request={current.request} onAnswer={(a) => queue.settle(current.id, a)} />}
    </DialogContext.Provider>
  )
}

const BUTTON =
  'inline-flex items-center gap-1.5 rounded-full border px-3.5 py-1.5 text-sm transition focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-400'

function RequestDialog({ request, onAnswer }: { request: Request; onAnswer: (answer: Answer) => void }) {
  const dialogRef = useRef<HTMLDialogElement>(null)
  const cancelRef = useRef<HTMLButtonElement>(null)
  const confirmRef = useRef<HTMLButtonElement>(null)
  const inputRef = useRef<HTMLInputElement>(null)
  const titleId = useId()
  const bodyId = useId()
  const inputId = useId()
  const danger = request.kind === 'confirm' && request.tone === 'danger'

  useEffect(() => {
    const dialog = dialogRef.current
    if (!dialog) return
    if (!dialog.open) {
      dialog.returnValue = ''
      dialog.showModal()
    }
    // React does not render the autofocus attribute that showModal() looks for, so place focus explicitly:
    // the safe Cancel action for destructive confirms, the field for prompts, otherwise the confirm button.
    if (request.kind === 'prompt') inputRef.current?.select()
    ;(request.kind === 'prompt' ? inputRef : danger ? cancelRef : confirmRef).current?.focus()
  }, [request.kind, danger])

  const onClose = () => {
    const dialog = dialogRef.current
    if (!dialog) return
    const value = dialog.returnValue
    // Esc and other close requests leave returnValue untouched; reset so a stale value cannot leak.
    dialog.returnValue = ''
    onAnswer(request.kind === 'confirm' ? confirmResult(value) : promptResult(value, inputRef.current?.value ?? ''))
  }

  const hasBody = request.kind === 'confirm' && request.body != null

  return (
    <dialog
      ref={dialogRef}
      aria-labelledby={titleId}
      aria-describedby={hasBody ? bodyId : undefined}
      onClose={onClose}
      className="app-dialog m-auto w-[min(28rem,calc(100vw-2rem))] rounded-2xl border border-white/10 bg-surface p-5 text-zinc-100 shadow-2xl"
    >
      <h2 id={titleId} className="text-base font-semibold text-zinc-50">
        {request.title}
      </h2>
      {/* method="dialog": the submit button closes the dialog with returnValue "confirm" (Enter in the field
          submits it too, after the native required/maxLength checks). */}
      <form method="dialog" className="mt-3">
        {request.kind === 'confirm' ? (
          hasBody && (
            <div id={bodyId} className="text-sm leading-relaxed text-zinc-300">
              {request.body}
            </div>
          )
        ) : (
          <>
            <label htmlFor={inputId} className="mb-1 block text-xs text-zinc-400">
              {request.label}
            </label>
            <input
              ref={inputRef}
              id={inputId}
              type="text"
              defaultValue={request.initial ?? ''}
              required
              maxLength={request.maxLength ?? DEFAULT_MAX_LENGTH}
              autoComplete="off"
              enterKeyHint="done"
              autoFocus
              className={cx(fieldClass, 'font-sans text-sm')}
            />
          </>
        )}
        <div className="mt-5 flex flex-wrap justify-end gap-2">
          {/* type="button" so it never becomes the form's default (implicit Enter) button. */}
          <button
            ref={cancelRef}
            type="button"
            autoFocus={danger}
            onClick={() => dialogRef.current?.close('cancel')}
            className={cx(BUTTON, 'border-white/10 bg-white/5 text-zinc-200 hover:border-white/25 hover:bg-white/10')}
          >
            {request.cancelLabel ?? DEFAULT_CANCEL}
          </button>
          <button
            ref={confirmRef}
            type="submit"
            value="confirm"
            autoFocus={request.kind === 'confirm' && !danger}
            className={cx(
              BUTTON,
              'font-medium',
              danger
                ? 'border-rose-400/50 bg-rose-500/20 text-rose-100 hover:bg-rose-500/30'
                : 'border-indigo-300/50 bg-indigo-500/25 text-indigo-50 hover:bg-indigo-500/35',
            )}
          >
            {request.confirmLabel}
          </button>
        </div>
      </form>
    </dialog>
  )
}
